using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public string BuyShip(int type){var d=C.ships[type];if(S.gold<d.price)return "金币不足";S.gold-=d.price;var ship=StateFactory.Ship(C,S.ownerId);ship.type=type;EnsureCrew(ship);S.ships.Add(ship);return "新船已入列，可在船坞设为旗舰或用于自动航线";}
        public string Flagship(int index){if(S.ships[index].busy)return "此船正在执行运输";if(Inventory.Weight(S.cargo)>C.ships[S.ships[index].type].capacity)return "货舱超重，请先卸货";var ship=S.ships[index];S.ships[index]=S.ships[0];S.ships[0]=ship;S.cargo.capacity=C.ships[ship.type].capacity;return "旗舰已更换";}
        public string Repair(){var sh=S.ships[0];int cost=(int)Math.Ceiling((C.initial.ship.hull-sh.hull)*C.balance.fleet.hullRepairPrice+(C.initial.ship.sails-sh.sails));if(HasPartner(C.balance.partnerRoles.carpenter))cost=(int)Math.Ceiling(cost*C.balance.fleet.repairPartnerFactor);if(S.gold<cost)return "维修金币不足";if(cost==0)return "船体与风帆完好";S.gold-=cost;sh.hull=C.initial.ship.hull;sh.sails=C.initial.ship.sails;Emit("repair");return "维修完成，支出 "+cost;}
        public string Supply(){var sh=S.ships[0];int cost=(int)Math.Ceiling(Math.Max(0,C.initial.ship.food-sh.food))+ExtraSupplyCost();if(S.gold<cost)return "补给金币不足";S.gold-=cost;sh.food=C.initial.ship.food;sh.ammo=C.initial.ship.ammo;RestoreSailingSupplies();return "食水与弹药已补满";}
        public string AddAuto(int to,string product,int n,int maxBuy,int minSell){if(!S.routes.Contains(S.city+">"+to))return "必须先亲自发现该方向航线";var ship=S.ships.Skip(1).FirstOrDefault(x=>!x.busy);if(ship==null)return "需要一艘非旗舰的空闲船";if(n<1||n*C.Product(product).weight>C.ships[ship.type].capacity)return "数量超过运输船容量";ship.busy=true;var route=StateFactory.Route(C);route.id=Guid.NewGuid().ToString("N");route.shipId=ship.id;route.from=S.city;route.to=to;route.product=product;route.quantity=n;route.maxBuy=maxBuy;route.minSell=minSell;route.cargo.capacity=C.ships[ship.type].capacity;S.autoRoutes.Add(route);return "运输订单已建立；运行中按真实库存与逐件市场报价结算";}
        public void StopAuto(AutoRoute a){if(a.status=="完成")return;a.status="暂停";a.reason="手动暂停";}
        public void ResumeAuto(AutoRoute a){if(a.status=="完成")return;a.reason="";a.status=a.cargo.batches.Count>0?"航行中":"装货中";}
        public string DeleteAuto(AutoRoute a){if(a.cargo.batches.Count>0&&a.progress<1)return "货物仍在海上，请继续运输到港后解除";var inv=S.cities[a.cargo.batches.Count>0?a.to:a.from].warehouse;if(Inventory.Weight(inv)+Inventory.Weight(a.cargo)>inv.capacity)return "目的仓库不足，无法卸货解除订单";foreach(var b in a.cargo.batches)Inventory.Add(inv,b.product,b.quality,b.quantity,b.origin);S.ships.First(x=>x.id==a.shipId).busy=false;S.autoRoutes.Remove(a);return "运输任务已解除，货物已存入任务目的港仓库";}
        internal void AdvanceAutoFleet(double dt){foreach(var a in S.autoRoutes.ToList()){if(a.status=="暂停"||a.status=="完成")continue;var ship=S.ships.First(x=>x.id==a.shipId);if(ship.hull<C.balance.fleet.autoMinimumHull||ship.food<C.balance.fleet.autoMinimumFood){a.status="暂停";a.reason="船体或补给不足，请解除任务后在船坞整备";continue;}if(a.status=="装货中"){int cost=Preview(a.from,a.product,a.quality,a.quantity,true),income=Preview(a.to,a.product,a.quality,a.quantity,false);if(Quote(a.from,a.product,a.quality,true)>a.maxBuy||Quote(a.to,a.product,a.quality,false)<a.minSell||income<=cost+C.balance.fleet.autoSupplyFee){a.status="暂停";a.reason="价格不符合限制或预计收入不足以覆盖补给费";continue;}if(Market(a.from,a.product).Stock(a.quality)<a.quantity+a.minReserve||S.gold<cost+C.balance.fleet.autoSupplyFee||a.budget<cost+C.balance.fleet.autoSupplyFee){a.status="暂停";a.reason="出发港缺货或预算不足";continue;}Trade(a.from,a.product,a.quality,a.quantity,true,a.cargo);S.gold-=C.balance.fleet.autoSupplyFee;a.spent=cost+C.balance.fleet.autoSupplyFee;a.budget-=cost+C.balance.fleet.autoSupplyFee;a.status="航行中";a.progress=0;}else if(a.status=="航行中"||a.status=="返航中"){a.progress+=dt/C.balance.fleet.autoLegSeconds;ship.food=Math.Max(0,ship.food-dt*C.balance.fleet.autoFoodPerSecond);if(a.progress<1)continue;if(a.status=="返航中"){a.status="装货中";a.progress=0;continue;}if(Quote(a.to,a.product,a.quality,false)<a.minSell||Market(a.to,a.product).stock+a.quantity>C.market.maxStock){a.status="暂停";a.reason="目的港价格过低或库存饱和";continue;}int before=S.gold;Trade(a.to,a.product,a.quality,a.quantity,false,a.cargo);a.budget+=S.gold-before;a.profit+=S.gold-before-a.spent;a.loops--;if(a.loops<=0){a.status="完成";ship.busy=false;}else{a.status="返航中";a.progress=0;}}}}
}}
